use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let path = input.as_str().unwrap();
    let mut parts = path.split('/').collect();
    let mut canonical_path = String::new();
    let mut current_part = String::new();
    for part in parts {
        if part == ".." {
            if current_part.is_empty() {
                continue;
            }
            current_part.pop();
        } else if part != "." {
            current_part.push(part);
        }
    }
    if canonical_path.is_empty() {
        Value::Null
    } else {
        Value::String(canonical_path)
    }
}
